css:
@property --koi-x-scale {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}
@property --koi-y-scale {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

[data-workspace-area="conversation"] {
  position: relative;
  isolation: isolate;
  container-type: size;
  background: radial-gradient(ellipse at 38% 28%, #151515, #101010 66%) !important;
}
[data-workspace-area="conversation"]::after {
  content: "";
  position: absolute;
  inset: 14% 15%;
  z-index: -2;
  pointer-events: none;
  background:
    radial-gradient(ellipse 54% 9% at 44% 35%, #ababab13, transparent 92%),
    radial-gradient(ellipse 47% 6% at 58% 44%, #a0a0a00c, transparent 92%),
    radial-gradient(ellipse 50% 13% at 66% 75%, #a0a0a00b, transparent 90%);
  transform: rotate(-10deg);
  opacity: .45;
}
@keyframes t3-pond-reflection {
  from { transform: translate(-7%, 3%) rotate(-10deg); opacity: .32; }
  to { transform: translate(8%, -4%) rotate(-5deg); opacity: .72; }
}
@media (prefers-reduced-motion: no-preference) {
  [data-workspace-area="conversation"]::after {
    animation: t3-pond-reflection 24s ease-in-out infinite alternate;
  }
}
[data-workspace-area="conversation"]::before {
  --koi-base: #e3d8c1;
  --koi-mark: #b45e43;
  --koi-deep: #70372b;
  --koi-fin: #a3856c;
  --koi-dark: #302a2a;
  --koi-duration: 112s;
  --koi-phase: -17s;
  content: "";
  position: absolute;
  inset: 0 auto auto 0;
  z-index: -1;
  pointer-events: none;
  width: 112px;
  height: 46px;
  opacity: .68;
  clip-path: path("M109 23 C109 15 103 11 94 11 C86 10 81 11 76 13 C69 9 63 5 53 4 C55 9 57 14 60 16 C49 17 41 21 31 21 C22 17 14 10 4 10 C7 17 11 23 13 24 C10 27 7 33 4 37 C16 36 21 29 31 26 C41 26 51 28 60 29 C58 34 55 39 53 42 C64 41 70 36 76 33 C81 35 86 36 94 35 C103 34 109 29 109 23 Z");
  background:
    radial-gradient(circle at 94% 38%, var(--koi-eye, #211d1d) 0 1px, transparent 1.9px),
    radial-gradient(circle at 94% 62%, var(--koi-eye, #211d1d) 0 1px, transparent 1.9px),
    radial-gradient(ellipse 8px 3px at 88% 47%, var(--koi-shine, #fff5e899), transparent),
    radial-gradient(ellipse 13px 8px at 79% 44%, var(--koi-mark) 65%, transparent 89%),
    radial-gradient(ellipse 8px 11px at 66% 58%, var(--koi-deep) 62%, transparent 85%),
    radial-gradient(ellipse 11px 8px at 57% 46%, var(--koi-mark) 65%, transparent 90%),
    radial-gradient(ellipse 8px 5px at 45% 60%, var(--koi-dark) 56%, transparent 85%),
    radial-gradient(ellipse 9px 4px at 37% 46%, var(--koi-mark) 55%, transparent 88%),
    radial-gradient(ellipse 40% 12% at 60% 47%, var(--koi-spine, #fff6de52), transparent),
    repeating-linear-gradient(24deg, transparent 0 4px, var(--koi-scales, #241d1d19) 5px, transparent 6px),
    linear-gradient(0deg, var(--koi-fin), var(--koi-base) 41% 58%, var(--koi-fin));
  --koi-track: t3-koi-main;
  --koi-x-scale: 1;
  --koi-y-scale: 1;
  transform-origin: 56px 23px;
  will-change: transform;
  animation: var(--koi-track) var(--koi-duration) linear var(--koi-phase) infinite;
}
[data-side-chat-pane] [data-workspace-area="conversation"]::before {
  --koi-base: #e5c68e;
  --koi-mark: #b88b47;
  --koi-deep: #735437;
  --koi-fin: #8c745a;
  --koi-dark: #4b3d2f;
  --koi-track: t3-koi-side;
  --koi-duration: 87s;
  --koi-phase: -41s;
  opacity: .59;
  scale: .72;
}
[data-side-chat-pane]:nth-child(even) [data-workspace-area="conversation"]::before {
  --koi-base: #ccd6df;
  --koi-mark: #8196ad;
  --koi-deep: #485469;
  --koi-fin: #73818f;
  --koi-dark: #303746;
}
@supports (width: calc(1px * random(1, 2))) {
  [data-workspace-area="conversation"]::before {
    --koi-x-scale: random(.83, 1.06);
    --koi-y-scale: random(.84, 1.06);
    --koi-duration: random(91s, 137s);
    --koi-phase: random(-86s, -2s);
  }
  [data-side-chat-pane] [data-workspace-area="conversation"]::before {
    --koi-duration: random(72s, 108s);
    --koi-phase: random(-65s, -3s);
  }
}
