@media (prefers-reduced-motion: reduce) {
  [data-workspace-area="conversation"]::before {
    animation: none;
    transform: translate(calc(27cqw - 56px), calc(60cqh - 23px)) rotate(-22deg);
    will-change: auto;
  }
}

:root:not(.dark) [data-workspace-area="conversation"] {
  background: radial-gradient(ellipse at 38% 28%, #f7f7f7, #e6e6e6 85%) !important;
}
:root:not(.dark) [data-workspace-area="conversation"]::after {
  background:
    radial-gradient(ellipse 52% 9% at 44% 35%, #ffffffea, transparent 91%),
    radial-gradient(ellipse 47% 6% at 58% 44%, #77777718, transparent 92%),
    radial-gradient(ellipse 48% 11% at 66% 75%, #ffffffaa, transparent 90%);
}
:root:not(.dark) [data-workspace-area="conversation"]::before { opacity: .96; }
:root:not(.dark) [data-side-chat-pane] [data-workspace-area="conversation"]::before { opacity: .85; }

:root:not(.dark) [data-workspace-area="conversation"]::before {
  --koi-base: #dddddd;
  --koi-mark: #555555;
  --koi-deep: #282828;
  --koi-fin: #878787;
  --koi-dark: #373737;
  --koi-eye: #171717;
  --koi-shine: #ffffff99;
  --koi-spine: #ffffff52;
  --koi-scales: #25252519;
}
:root:not(.dark) [data-side-chat-pane] [data-workspace-area="conversation"]::before {
  --koi-base: #b5b5b5;
  --koi-mark: #5b5b5b;
  --koi-deep: #333333;
  --koi-fin: #747474;
  --koi-dark: #424242;
}
:root:not(.dark) [data-side-chat-pane]:nth-child(even) [data-workspace-area="conversation"]::before {
